function updateNavBadge() {
  const t = totals(getState().invoices);
  const badge = document.getElementById("navPending");
  if (!badge) return;
  if (t.pendingCount > 0) {
    badge.hidden = false;
    badge.textContent = String(t.pendingCount);
  } else {
    badge.hidden = true;
  }
}
